package com.gwtplatform.carstore.cucumber.application.widgets;
public class MessageWidgetPage extends BasePage {
    public Boolean hasSuccessMessage() {
        return hasSuccessMessage("");
    }
    public Boolean hasSuccessMessage(String message) {
        return messageContains("successMessage", message) && messageIsVisible(getSuccessMessage());
    }
    public Boolean hasErrorMessage() {
        return messageIsVisible(getErrorMessage());
    }
    public void hideSuccessMessage() {
        hideMessage(getSuccessMessage());
    }
    public void hideErrorMessage() {
        hideMessage(getErrorMessage());
    }
    public void waitUntilSuccessMessageIsHidden(String message) {
        messageContains("successMessage", message);
        waitUntilElementIsDetached(getSuccessMessage());
    }
    private Boolean messageIsVisible(WebElement element) {
        try {
            waitUntilElementIsVisible(element);
            return true;
        } catch (TimeoutException e) {
            return false;
        }
    }
    private boolean messageContains(String debugId, String message) {
        WebElement container = webDriver.findElement(ByDebugId.id(debugId));
        while (container != null) {
            WebElement content = container.findElement(By.cssSelector("span"));
            if (!Strings.isNullOrEmpty(content.getText()) && content.getText().contains(message)) {
                return true;
            }
            hideMessage(container);
            container = getMessageContainer(ByDebugId.id(debugId));
        }
        return false;
    }
    private void hideMessage(WebElement message) {
        WebElement close = message.findElement(By.cssSelector("span:last-child"));
        close.click();
        waitUntilElementIsDetached(message);
    }
    private WebElement getMessageContainer(By by) {
        try {
            return webDriver.findElement(by);
        } catch (NoSuchElementException e) {
            return null;
        }
    }
    private WebElement getSuccessMessage() {
        return waitUntilElementIsVisible(ByDebugId.id("successMessage"));
    }
    private WebElement getErrorMessage() {
        return waitUntilElementIsVisible(ByDebugId.id("errorMessage"));
    }
}
package com.gwtplatform.carstore.cucumber.stepdefs;
@ScenarioScoped
public class ManufacturersStepDefs extends StepDefs {
    private static final int animationTimeout = 1500;
    private final ManufacturersPage manufacturersPage;
    private final ManufacturersEditPage manufacturersEditPage;
    private final MessageWidgetPage messageWidgetPage;
    private int numberOfLines;
    @Inject
    ManufacturersStepDefs(
            ManufacturersPage manufacturersPage,
            ManufacturersEditPage manufacturersEditPage,
            MessageWidgetPage messageWidgetPage) {
        this.manufacturersPage = manufacturersPage;
        this.manufacturersEditPage = manufacturersEditPage;
        this.messageWidgetPage = messageWidgetPage;
    }
    @Given("^I click on the create manufacturer button$")
    public void I_click_on_create_manufacturer_button() {
        numberOfLines = manufacturersPage.getNumberOfLines();
        manufacturersPage.clickOnCreate();
        sleep(animationTimeout);
    }
    @When("^I click on the first manufacturer edit button$")
    public void I_click_on_first_manufacturer_edit_button() {
        manufacturersPage.editFirstManufacturer();
        sleep(animationTimeout);
    }
    @When("^I enter (\\S+) as the car manufacturer$")
    public void I_enter_as_manufacturer(String manufacturer) {
        manufacturersEditPage.setManufacturer(manufacturer);
    }
    @When("^I click on the save button$")
    public void I_click_on_the_save_button() {
        manufacturersEditPage.clickOnSave();
    }
    @When("^I click on the close button$")
    public void I_click_on_the_close_button() {
        manufacturersEditPage.clickOnClose();
    }
    @When("^I delete the first manufacturer$")
    public void I_delete_first_car() {
        numberOfLines = manufacturersPage.getNumberOfLines();
        manufacturersPage.deleteFirstManufacturer();
    }
    @Then("^I see the manufacturer editor$")
    public void I_see_manufacturer_editor() {
        assertTrue(manufacturersEditPage.isManufacturerEditorVisible());
    }
    @Then("^The shown manufacturer should match the edited manufacturer$")
    public void The_shown_manufacturer_should_match_the_edited_manufacturer() {
        assertEquals(manufacturersEditPage.getManufacturer(), manufacturersPage.getFirstManufacturer());
    }
    @Then("^The manufacturer table should show (\\S+) as the first manufacturer$")
    public void Manufacturer_table_should_show_as_first_manufacturer(String manufacturer) {
        assertEquals(manufacturersPage.getFirstManufacturer(), manufacturer);
    }
    @Then("^The manufacturer table should show (\\S+) as the last manufacturer$")
    public void Manufacturer_table_should_show_as_last_manufacturer(String manufacturer) {
        assertEquals(manufacturersPage.getLastManufacturer(), manufacturer);
    }
    @Then("^The first manufacturer gets removed$")
    public void First_car_gets_removed() {
        assertEquals(numberOfLines - 1, manufacturersPage.getNumberOfLines());
    }
    @Then("^The number of rows is unchanged$")
    public void Number_of_rows_is_unchanged() {
        assertEquals(manufacturersPage.getNumberOfLines(), numberOfLines);
    }
    @Then("^The number of rows is incremented$")
    public void Number_of_rows_is_incremented() {
        assertTrue(manufacturersPage.getNumberOfLines() > numberOfLines);
    }
}
package com.gwtplatform.carstore.cucumber.stepdefs;
@ScenarioScoped
public class RatingStepdefs {
    private final RatingPage ratingPage;
    private final MessageWidgetPage messageWidgetPage;
    private int numberOfLines;
    @Inject
    RatingStepdefs(
            RatingPage ratingPage,
            MessageWidgetPage messageWidgetPage) {
        this.ratingPage = ratingPage;
        this.messageWidgetPage = messageWidgetPage;
    }
    @Given("^I click on the create rating button$")
    public void iClickOnTheCreateRatingButton() {
        numberOfLines = ratingPage.getNumberOfLines();
        ratingPage.clickOnCreate();
    }
    @When("^I fill the rating form$")
    public void iFillTheRatingForm() {
        ratingPage.fillForm();
    }
    @Then("^A rating is created$")
    public void aRatingIsCreated() {
        assertTrue(messageWidgetPage.hasSuccessMessage());
        assertEquals(numberOfLines + 1, ratingPage.getNumberOfLines());
    }
    @When("^I delete the first rating$")
    public void iDeleteTheFirstRating() {
        numberOfLines = ratingPage.getNumberOfLines();
        ratingPage.deleteFirstRating();
    }
    @Then("^The first rating gets removed$")
    public void theFirstRatingGetsRemoved() {
        assertEquals(numberOfLines - 1, ratingPage.getNumberOfLines());
    }
}
package com.gwtplatform.carstore.cucumber.stepdefs;
@ScenarioScoped
public class ReportStepDefs {
    private static final String CAR_COL = "Car";
    private static final String RATING_COL = "Rating";
    private final RatingPage ratingPage;
    private final ReportPage reportPage;
    @Inject
    ReportStepDefs(
            RatingPage ratingPage,
            ReportPage reportPage) {
        this.ratingPage = ratingPage;
        this.reportPage = reportPage;
    }
    @Given("^I compute rating average for all manufacturers$")
    public void I_compute_rating_average_for_all_manufacturers() {
        int numberOfLines = ratingPage.getNumberOfLines();
        for (int line = 1; line <= numberOfLines; line++) {
            String car = ratingPage.getCellText(CAR_COL, line);
            String rating = ratingPage.getCellText(RATING_COL, line);
            reportPage.addRating(car, rating);
        }
    }
    @Then("^I see the proper averages for all manufacturers$")
    public void I_see_proper_averages_for_all_manufacturers() {
        assertTrue(reportPage.checkManufacturerAverages());
    }
}

