import { Injectable, signal } from '@angular/core';
export interface Message { id: number; text: string; style: 'success' | 'error'; }
@Injectable({ providedIn: 'root' })
export class MessageService {
  private seq = 0;
  readonly messages = signal<Message[]>([]);
  success(text: string) { this.add(text, 'success'); }
  error(text: string) { this.add(text, 'error'); }
  private add(text: string, style: 'success' | 'error') {
    const m = { id: ++this.seq, text, style };
    this.messages.update(l => [...l, m]);
    setTimeout(() => this.close(m), 8000);
  }
  close(m: Message) { this.messages.update(l => l.filter(x => x !== m)); }
}
