import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService, ManufacturerDto } from './api.service';
import { MessageService } from './message.service';
@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [FormsModule],
  template: `
    <h2>Manufacturers</h2>
    <button id="gwt-debug-create-manufacturer" (click)="create()">Create</button>
    <table id="gwt-debug-manufacturers" class="grid">
      <thead><tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr></thead>
      <tbody>
        @for (m of manufacturers(); track m.id) {
          <tr><td>{{ m.id }}</td><td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (editing(); as e) {
      <div class="glass"></div>
      <div id="gwt-debug-manufacturer-editor" class="popup">
        <h3>{{ e.id ? 'Edit manufacturer' : 'Create manufacturer' }}</h3>
        <label>Name <input id="gwt-debug-manufacturer-input" type="text" [(ngModel)]="name" /></label>
        <div class="buttons">
          <button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="editing.set(null)">Close</button>
        </div>
      </div>
    }
  `,
})
export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  manufacturers = signal<ManufacturerDto[]>([]);
  editing = signal<ManufacturerDto | null>(null);
  name = '';
  ngOnInit() { this.load(); }
  load() {
    this.api.getManufacturers().subscribe({ next: l => this.manufacturers.set(l), error: () => this.msg.error('Error retrieving manufacturers') });
  }
  create() { this.name = ''; this.editing.set({}); }
  edit(m: ManufacturerDto) { this.name = m.name ?? ''; this.editing.set(m); }
  save() {
    const e = this.editing();
    if (!e) return;
    const dto: ManufacturerDto = { ...e, name: this.name };
    this.api.saveManufacturer(dto).subscribe({
      next: saved => {
        this.msg.success('Manufacturer saved');
        this.editing.set(null);
        this.manufacturers.update(l => {
          const i = l.findIndex(x => x.id === saved.id);
          if (i >= 0) { const c = [...l]; c[i] = saved; return c; }
          return [...l, saved];
        });
      },
      error: () => this.msg.error('Error saving manufacturer'),
    });
  }
  remove(m: ManufacturerDto) {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) return;
    this.api.deleteManufacturer(m.id as number).subscribe({
      next: () => { this.manufacturers.update(l => l.filter(x => x !== m)); this.msg.success('Manufacturer deleted'); },
      error: () => this.msg.error('Error deleting manufacturer'),
    });
  }
}
