import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService, CarDto, RatingDto, carLabel } from './api.service';
import { MessageService } from './message.service';
@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <h2>Ratings</h2>
    <button id="gwt-debug-ratingCreate" (click)="create()">Create</button>
    @if (creating()) {
      <div class="glass"></div>
      <div class="popup">
        <h3>Create rating</h3>
        <label>Car <select [(ngModel)]="car">
          @for (c of cars(); track c.id) { <option [ngValue]="c">{{ label(c) }}</option> }
        </select></label>
        <label>Rating <input id="gwt-debug-ratingInput" type="text" [(ngModel)]="rating" /></label>
        <div class="buttons">
          <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="creating.set(false)">Close</button>
        </div>
      </div>
    }
    <table id="gwt-debug-ratings" class="grid">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
      <tbody>
        @for (r of ratings(); track r.id) {
          <tr><td>{{ r.id }}</td><td>{{ label(r.car) }}</td><td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td></tr>
        }
      </tbody>
    </table>
  `,
})
export class RatingComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  ratings = signal<RatingDto[]>([]);
  cars = signal<CarDto[]>([]);
  creating = signal(false);
  car: CarDto | null = null;
  rating = '';
  label = carLabel;
  ngOnInit() {
    this.api.getRatings().subscribe({ next: l => this.ratings.set(l), error: () => this.msg.error('Error retrieving ratings') });
  }
  create() {
    this.rating = '';
    this.creating.set(true);
    this.api.getCars().subscribe({
      next: l => { this.cars.set(l); if (!this.car || !l.some(c => c.id === this.car?.id)) this.car = l[0] ?? null; else this.car = l.find(c => c.id === this.car?.id) ?? null; },
      error: () => this.msg.error('Error retrieving cars'),
    });
  }
  save() {
    const value = parseInt(this.rating, 10);
    if (isNaN(value)) { this.msg.error('Invalid rating'); return; }
    this.api.saveRating({ rating: value, car: this.car }).subscribe({
      next: saved => { this.creating.set(false); this.ratings.update(l => [...l, saved]); this.msg.success('Rating saved'); },
      error: () => this.msg.error('Error saving rating'),
    });
  }
  remove(r: RatingDto) {
    if (!window.confirm('Are you sure you want to delete' + carLabel(r.car) + '?')) return;
    this.api.deleteRating(r.id as number).subscribe({
      next: () => { this.ratings.update(l => l.filter(x => x !== r)); this.msg.success('Rating deleted'); },
      error: () => this.msg.error('Error deleting rating'),
    });
  }
}
